"""Generic, read-only Sector Console renderer for AWG CITA."""

INDEX_HTML = r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AWG CITA · Sector Console</title><style>:root{--bg:#0c0c0d;--panel:#151416;--line:#403b3b;--text:#f0eadb;--dim:#aaa297;--red:#e8443f;--ok:#97c59d;--mono:Consolas,monospace}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Arial,sans-serif}.shell{min-height:100vh;display:grid;grid-template-columns:220px 1fr}.rail{padding:24px 16px;border-right:1px solid var(--line)}.brand{font:700 17px var(--mono);letter-spacing:.08em}.brand i{color:var(--red);font-style:normal}.rail small,.eyebrow,th{color:var(--dim);font:10px var(--mono);letter-spacing:.08em;text-transform:uppercase}.nav{display:grid;gap:4px;margin-top:34px}.nav span{padding:10px;border-left:3px solid var(--red);background:var(--panel)}main{min-width:0;padding:0 30px 28px}.top{height:42px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font:10px var(--mono);color:var(--ok)}.head{display:flex;justify-content:space-between;gap:20px;align-items:end;padding:36px 0 22px;border-bottom:1px solid var(--line)}h1{margin:5px 0;font-size:clamp(34px,5vw,56px);line-height:.95;text-transform:uppercase}.sub{margin:12px 0 0;color:var(--dim)}button{min-height:38px;padding:0 12px;border:1px solid var(--line);background:var(--panel);color:var(--text);cursor:pointer}.primary{background:var(--red);color:#160909;border-color:var(--red);font-weight:bold}.language-menu{position:relative;display:inline-block}.language-list{position:absolute;right:0;top:43px;z-index:2;width:150px;padding:4px;background:var(--panel);border:1px solid var(--line)}.language-list[hidden]{display:none}.language-list button{display:block;width:100%;border:0;text-align:left}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);margin:22px 0}.metric{min-height:104px;padding:16px;border-right:1px solid var(--line)}.metric:last-child{border:0}.metric strong{display:block;margin-top:13px;font:700 28px var(--mono)}.ok{color:var(--ok)}.work{display:grid;grid-template-columns:1fr 280px;border:1px solid var(--line)}.section-head{padding:15px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:12px}.filter{background:#101011;color:var(--text);border:1px solid var(--line);padding:7px;font:11px var(--mono)}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:13px;border-bottom:1px solid var(--line);text-align:left;overflow-wrap:anywhere}td{font-size:13px}.row{cursor:pointer}.row.selected td{background:#221d1e}.state{font:10px var(--mono);color:var(--ok)}.inspector{border-left:1px solid var(--line);background:#111112}.facts{padding:15px}.facts h2{margin:0 0 10px}.facts dl{border-top:1px solid var(--line)}dt{margin-top:12px;color:var(--dim);font:9px var(--mono);text-transform:uppercase}dd{margin:4px 0;font:12px var(--mono)}.disabled{opacity:.5;cursor:not-allowed;width:100%;margin-top:9px}.gate{padding:12px;border:1px solid #8f2524;color:#f0b0a8;font:11px var(--mono)}.modal{position:fixed;inset:0;display:none;place-items:center;background:#050505c9}.modal.open{display:grid}.dialog{width:min(460px,92vw);padding:18px;border:1px solid var(--red);background:var(--panel)}@media(max-width:780px){.shell{grid-template-columns:1fr}.rail{display:none}main{padding:0 16px 22px}.metrics{grid-template-columns:repeat(2,1fr)}.metric:nth-child(2){border-right:0}.metric:nth-child(-n+2){border-bottom:1px solid var(--line)}.work{grid-template-columns:1fr}.inspector{border-left:0;border-top:1px solid var(--line)}th:nth-child(3),td:nth-child(3),th:nth-child(5),td:nth-child(5),th:nth-child(6),td:nth-child(6){display:none}.head{align-items:stretch;flex-direction:column}}</style></head><body><div class="shell"><aside class="rail"><div class="brand"><i>◇</i> AWG CITA</div><small data-i18n="node">ОПЕРАТОРСКАЯ КОНСОЛЬ</small><div class="nav"><span data-i18n="overview">Обзор</span><span data-i18n="clients">Клиенты</span></div></aside><main id="dashboard" data-runtime="read_only" aria-busy="true"><div class="top"><span data-i18n="perimeter">ЛОКАЛЬНЫЙ КОНТУР</span><span id="connection">—</span></div><header class="head"><div><div class="eyebrow" data-i18n="summary">01 — СВОДКА</div><h1 data-i18n="title">Узел<br>управления</h1><p class="sub" data-i18n="sub">Безопасная read-only телеметрия AmneziaWG.</p></div><div><div class="language-menu"><button id="language-toggle">RU ▾</button><div class="language-list" id="language-list" hidden><button data-lang="ru">Русский</button><button data-lang="en">English</button><button data-lang="es">Español</button><button data-lang="zh">简体中文</button><button data-lang="de">Deutsch</button><button data-lang="fr">Français</button></div></div><button id="refresh" data-i18n="refresh">Обновить</button><button id="add" class="primary" data-i18n="add">Добавить клиента</button></div></header><section class="metrics"><article class="metric"><small data-i18n="state">Состояние</small><strong id="state">—</strong></article><article class="metric"><small data-i18n="active">Активны</small><strong id="online">—</strong></article><article class="metric"><small data-i18n="traffic">Трафик сессии</small><strong id="session-total">—</strong></article><article class="metric"><small data-i18n="attention">Внимание</small><strong id="attention">—</strong></article></section><section class="work"><div><div class="section-head"><b data-i18n="clients">Клиенты</b><input id="filter" class="filter" data-i18n-placeholder="filter" placeholder="ФИЛЬТР"></div><table><thead><tr><th data-i18n="client">Клиент</th><th data-i18n="state">Состояние</th><th data-i18n="handshake">Handshake</th><th data-i18n="totalTraffic">Всего трафика</th><th data-i18n="rx">Получено</th><th data-i18n="tx">Отправлено</th></tr></thead><tbody id="peers"></tbody></table></div><aside class="inspector"><div class="section-head"><b data-i18n="dossier">Досье</b></div><div class="facts"><h2 id="inspect-name">—</h2><p data-i18n="safe">Ключи, endpoints и адреса не отображаются.</p><dl><dt data-i18n="totalTraffic">Всего трафика</dt><dd id="inspect-total">—</dd><dt data-i18n="rx">Получено</dt><dd id="inspect-rx">—</dd><dt data-i18n="tx">Отправлено</dt><dd id="inspect-tx">—</dd></dl><button class="disabled" disabled data-i18n="config">Сформировать конфигурацию</button></div></aside></section></main></div><div id="modal" class="modal"><div class="dialog"><h2 data-i18n="add">Добавить клиента</h2><p class="gate" data-i18n="gate">ДЕЙСТВИЕ НЕДОСТУПНО: runtime read-only.</p><button id="close" data-i18n="close">Закрыть</button></div></div><script>const el=id=>document.getElementById(id);let data,selected=0,lang='ru';const tr={ru:{node:'ОПЕРАТОРСКАЯ КОНСОЛЬ',overview:'Обзор',clients:'Клиенты',perimeter:'ЛОКАЛЬНЫЙ КОНТУР',summary:'01 — СВОДКА',title:'Узел<br>управления',sub:'Безопасная read-only телеметрия AmneziaWG.',refresh:'Обновить',add:'Добавить клиента',state:'Состояние',active:'Активны',traffic:'Трафик сессии',attention:'Внимание',filter:'ФИЛЬТР',client:'Клиент',handshake:'Handshake',totalTraffic:'Всего трафика',rx:'Получено',tx:'Отправлено',dossier:'Досье',safe:'Ключи, endpoints и адреса не отображаются.',config:'Сформировать конфигурацию',gate:'ДЕЙСТВИЕ НЕДОСТУПНО: runtime read-only.',close:'Закрыть'},en:{node:'OPERATOR CONSOLE',overview:'Overview',clients:'Clients',perimeter:'LOCAL PERIMETER',summary:'01 — SUMMARY',title:'Management<br>node',sub:'Safe read-only AmneziaWG telemetry.',refresh:'Refresh',add:'Add client',state:'State',active:'Active',traffic:'Session traffic',attention:'Attention',filter:'FILTER',client:'Client',handshake:'Handshake',totalTraffic:'Total traffic',rx:'Received',tx:'Sent',dossier:'Dossier',safe:'Keys, endpoints and addresses are not shown.',config:'Generate configuration',gate:'ACTION UNAVAILABLE: runtime is read-only.',close:'Close'},es:{},zh:{},de:{},fr:{}};for(const k of ['es','zh','de','fr'])tr[k]=tr.en;const t=k=>tr[lang][k]||tr.en[k]||k;const bytes=n=>{n=Number(n)||0;let u='B';for(const x of ['KB','MB','GB']){if(n<1024)break;n/=1024;u=x}return n.toFixed(u==='B'?0:1)+' '+u};function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(n=>n.innerHTML=t(n.dataset.i18n));document.querySelectorAll('[data-i18n-placeholder]').forEach(n=>n.placeholder=t(n.dataset.i18nPlaceholder));el('language-toggle').textContent=lang.toUpperCase()+' ▾';render()}function render(){const ps=data?.peers||[],q=el('filter').value.toLowerCase();const p=ps[selected]||{};el('peers').innerHTML=ps.map((x,i)=>`<tr class="row ${i===selected?'selected':''}" data-i="${i}"><td>Peer ${i+1}</td><td class="state">${x.status}</td><td>${x.latest_handshake||'—'}</td><td>${bytes((x.rx_bytes||0)+(x.tx_bytes||0))}</td><td>${bytes(x.rx_bytes)}</td><td>${bytes(x.tx_bytes)}</td></tr>`).filter(x=>x.toLowerCase().includes(q)).join('')||'<tr><td colspan="6">—</td></tr>';document.querySelectorAll('.row').forEach(r=>r.onclick=()=>{selected=Number(r.dataset.i);render()});el('inspect-name').textContent=ps[selected]?'Peer '+(selected+1):'—';el('inspect-total').textContent=bytes((p.rx_bytes||0)+(p.tx_bytes||0));el('inspect-rx').textContent=bytes(p.rx_bytes);el('inspect-tx').textContent=bytes(p.tx_bytes)}async function refresh(){try{const r=await fetch('/api/status',{cache:'no-store'});data=await r.json();el('state').textContent=data.state;el('online').textContent=data.summary?.online??'—';el('session-total').textContent=bytes((data.summary?.rx_bytes||0)+(data.summary?.tx_bytes||0));el('attention').textContent=(data.summary?.stale||0)+(data.summary?.offline||0)+(data.summary?.never||0);el('connection').textContent=r.ok?'● OK':'● ERROR';render()}finally{el('dashboard').setAttribute('aria-busy','false')}}el('refresh').onclick=refresh;el('filter').oninput=render;el('language-toggle').onclick=()=>el('language-list').hidden=!el('language-list').hidden;document.querySelectorAll('[data-lang]').forEach(n=>n.onclick=()=>{lang=n.dataset.lang;el('language-list').hidden=true;translate()});el('add').onclick=()=>el('modal').classList.add('open');el('close').onclick=()=>el('modal').classList.remove('open');translate();refresh();setInterval(refresh,5000);</script></body></html>'''
